package com.portfolio.features.project.repository; import com.portfolio.features.project.entity.Project; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.EntityGraph; public interface ProjectRepository extends JpaRepository<Project,UUID>{@EntityGraph(attributePaths="technologies") List<Project> findByPortfolioIdOrderBySortOrderAscTitleAsc(UUID id); boolean existsByPortfolioId(UUID id); boolean existsByPortfolioIdAndSlug(UUID id,String slug);}
